/** Join fields into one CSV line. Fields have no commas or quotes. */
export function joinCsvLine(fields) {
  return fields.join(",");
}

/** Split one CSV line into fields; a comma inside double quotes stays in its field. */
export function parseCsvLine(line) {
  const fields = [];
  let field = "";
  let quoted = false;
  for (const ch of line) {
    if (ch === '"') quoted = !quoted;
    else if (ch === "," && !quoted) {
      fields.push(field);
      field = "";
    } else field += ch;
  }
  fields.push(field);
  return fields;
}
